1	import React, { useRef, useState, useEffect } from 'react';
2	import axios from 'axios';
3	import VideocamOffIcon from '@mui/icons-material/VideocamOff';
4	import Sidebar from '../components/Sidebar';
5	import SafeMuiIcon from '../components/SafeMuiIcon';
6	import { DECISION_STATES } from '../components/RecognitionDecisionCard';
7	import EvaluationRecorderModal from '../components/EvaluationRecorderModal';
8	import LiveConfusionMatrixPanel from '../components/LiveConfusionMatrixPanel';
9	import useEvaluationParticipants from '../hooks/useEvaluationParticipants';
10	import SecurityLogIcon from '../components/SecurityLogIcon';
11	import '../css/Dashboard.css';
12	import '../css/VPatrol.css';
13	import {
14	  PI_CAMERA_STREAM_URL,
15	  CAMERA_SOURCES,
16	  CAMERA_STATUS_MESSAGES,
17	  isPiCameraReachable,
18	  fetchPiSnapshotBitmap,
19	} from '../constants/piCamera';
20	import { API_BASE_URL } from '../constants/api';
21	import { clampBoxToFrame, faceBoxStyle } from '../constants/faceBox';
22	import { describeRecognitionSubject, RECOGNITION_STATUS } from '../constants/recognition';
23	import { formatSingaporeTimestamp, formatSingaporeFull } from '../constants/datetime';
24	import { loadLabelMap, buildEvaluationDraftFromRecognition, loadRecords, saveRecords, saveEvaluationRecordFromDraft, notifyEvaluationRecordsUpdated, DETECTION_OUTCOMES } from '../constants/evaluation';
25	import {
26	  deriveAccessResult,
27	  getLogTimestamp,
28	  filterSecurityLogs,
29	  hasActiveFilters,
30	  DATE_FILTERS,
31	  EVENT_FILTERS,
32	} from '../constants/securityTimeline';
33	import {
34	  SCAN_INTERVAL_MS,
35	  TARGET_LOCK_MS,
36	  CAPTURE_MAX_WIDTH,
37	  SERVICE_UNAVAILABLE_MSG,
38	  createScanGate,
39	  startTimer,
40	  logScanTimings,
41	} from '../constants/scanControl';
42	
43	const MATRIX_ORIGIN = 'V-Patrol';
44	
45	const VPatrol = () => {
46	  const videoRef = useRef(null);
47	  const canvasRef = useRef(null);
48	  const containerRef = useRef(null); // preview container, for face-box projection
49	
50	  // Camera source: Raspberry Pi Gate Camera is primary, laptop webcam is fallback
51	  const [cameraSource, setCameraSource] = useState(CAMERA_SOURCES.PI);
52	  const [cameraStatusMsg, setCameraStatusMsg] = useState("Connecting to Pi Gate Camera...");
53	  const cameraSourceRef = useRef(CAMERA_SOURCES.PI);
54	  const piFailStreakRef = useRef(0);
55	
56	  // Staged States: SYSTEM_ACTIVE, PRESENCE_DETECTED, TARGET_LOCKING, LIVENESS_CHECK, SECURE_MATCH, UNKNOWN_QUERY
57	  const [scanStatus, setScanStatus] = useState("SYSTEM_ACTIVE");
58	  const [identifiedUser, setIdentifiedUser] = useState(null);
59	  const [faceBox, setFaceBox] = useState(null);
60	  const [scanProgress, setScanProgress] = useState(0);
61	
62	  const scanStatusRef = useRef("SYSTEM_ACTIVE");
63	  const lockTimerRef = useRef(null);
64	  const progressIntervalRef = useRef(null);
65	
66	  // No-overlap + AI-error-backoff guard for the scan loop.
67	  const scanGateRef = useRef(createScanGate());
68	  const [serviceNotice, setServiceNotice] = useState('');
69	  const [lastDecision, setLastDecision] = useState(null);
70	  const [evalModal, setEvalModal] = useState({ open: false, draft: null });
71	  const [scanMode, setScanMode] = useState('operational');
72	  const [evaluationConfig, setEvaluationConfig] = useState({ actualLabel: '', condition: 'Front', autoRecord: true });
73	  const { participants, labels: participantLabels, loading: participantsLoading, error: participantsError } = useEvaluationParticipants();
74	  const scanModeRef = useRef('operational');
75	  const evaluationConfigRef = useRef({ actualLabel: '', condition: 'Front', autoRecord: true });
76	  const lastRecordedScanRef = useRef(null);
77	  // Switching modes clears the previous decision so the evaluation accordion
78	  // only ever shows results produced in Live Evaluation Mode.
79	  const updateScanMode = (mode) => { setScanMode(mode); scanModeRef.current = mode; lastRecordedScanRef.current = null; setLastDecision(null); };
80	  const updateEvaluationConfig = (next) => { setEvaluationConfig(next); evaluationConfigRef.current = next; };
81	
82	  // LIVENESS MEMORY: Tracks the head-turn validation
83	  const candidateUserRef = useRef(null);
84	  const lastLogRef = useRef({ name: null, timestamp: 0 });
85	
86	  const [systemTime, setSystemTime] = useState(new Date().toLocaleTimeString('en-SG', {
87	    hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true
88	  }));
89	
90	  const [incidentLogs, setIncidentLogs] = useState([]);
91	
92	  // Compact timeline filters (frontend-only filtering of the loaded records).
93	  const [dateFilter, setDateFilter] = useState('all');
94	  const [eventFilter, setEventFilter] = useState('all');
95	  const [searchFilter, setSearchFilter] = useState('');
96	
97	  const token = localStorage.getItem("accessToken");
98	  // All recognition traffic goes through the Node backend - never FastAPI directly.
99	  const NODE_SERVER_URL = `${API_BASE_URL}/api/security/logs`;
100	  const RECOGNIZE_URL = `${API_BASE_URL}/api/facial-recognition/recognize`;
101	  const EVALUATE_URL = `${API_BASE_URL}/api/facial-recognition/evaluate`;
102	  // V-Patrol is a monitoring post: it records access AUDIT events only and must
103	  // never toggle clock-in/out (that belongs to the Gate Scanner's scan endpoint).
104	  const ACCESS_EVENT_URL = `${API_BASE_URL}/api/facial-recognition/access-event`;
105	  const CAMERA_LOCATION = "Biometric Gantry";
106	
107	  const cameraSourceLabel = cameraSource === CAMERA_SOURCES.PI ? 'Raspberry Pi Gate Camera' : 'Laptop Webcam';
108	
109	  // Recording ground truth only stores one local evaluation record - it never
110	  // re-runs recognition and never creates Attendance or SecurityLogs.
111	  const openEvaluationRecorder = (result) => {
112	    const draft = buildEvaluationDraftFromRecognition({ result, labelMap: loadLabelMap(), origin: MATRIX_ORIGIN });
113	    setEvalModal({ open: true, draft });
114	  };
115	
116	  const handleEvaluationSaved = () => {
117	    setEvalModal({ open: false, draft: null });
118	    setLastDecision((prev) => prev ? { ...prev, evaluationMessage: 'Live evaluation result recorded' } : prev);
119	  };
120	
121	  const changeScanState = (nextState) => {
122	    setScanStatus(nextState);
123	    scanStatusRef.current = nextState;
124	  };
125	
126	  useEffect(() => {
127	    initCameraSource();
128	
129	    // FETCH PERMANENT LOGS ON LOAD
130	    axios.get(NODE_SERVER_URL, { headers: { Authorization: `Bearer ${token}` } })
131	      .then(res => {
132	        if (res.data && res.data.length > 0) {
133	          setIncidentLogs(res.data);
134	        } else {
135	          setIncidentLogs([{ id: 'SYS-001', occurredAt: new Date().toISOString(), type: 'System Online', desc: 'Biometric sensors initialized.', severity: 'safe', icon: 'OK' }]);
136	        }
137	      })
138	      .catch(err => {
139	        console.error("Database connection waiting...", err);
140	        setIncidentLogs([{ id: 'SYS-001', occurredAt: new Date().toISOString(), type: 'System Offline', desc: 'Cannot connect to security database.', severity: 'critical', icon: 'WARNING' }]);
141	      });
142	
143	    const clockInterval = setInterval(() => {
144	      setSystemTime(new Date().toLocaleTimeString('en-SG', {
145	        hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true
146	      }));
147	    }, 1000);
148	
149	    const scanInterval = setInterval(() => {
150	      performLiveScan();
151	    }, SCAN_INTERVAL_MS);
152	
153	    return () => {
154	      stopCCTV();
155	      clearInterval(clockInterval);
156	      clearInterval(scanInterval);
157	      if (lockTimerRef.current) clearTimeout(lockTimerRef.current);
158	      if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
159	    };
160	  }, []);
161	
162	  const applyCameraSource = (source, statusMsg) => {
163	    cameraSourceRef.current = source;
164	    setCameraSource(source);
165	    setCameraStatusMsg(statusMsg);
166	    piFailStreakRef.current = 0;
167	  };
168	
169	  // Primary source: Raspberry Pi Gate Camera. Probe the snapshot endpoint on
170	  // load; if unreachable, automatically fall back to the laptop webcam.
171	  const initCameraSource = async () => {
172	    const piReachable = await isPiCameraReachable();
173	    if (piReachable) {
174	      stopCCTV();
175	      applyCameraSource(CAMERA_SOURCES.PI, CAMERA_STATUS_MESSAGES.PI_CONNECTED);
176	      changeScanState("SYSTEM_ACTIVE");
177	    } else {
178	      applyCameraSource(CAMERA_SOURCES.WEBCAM, CAMERA_STATUS_MESSAGES.PI_UNAVAILABLE);
179	      await startCCTV();
180	    }
181	  };
182	
183	  // Manual camera source switch (Pi Gate Camera / Laptop Webcam)
184	  const selectCameraSource = async (source) => {
185	    if (source === cameraSourceRef.current) return;
186	    if (source === CAMERA_SOURCES.PI) {
187	      const piReachable = await isPiCameraReachable();
188	      if (piReachable) {
189	        stopCCTV();
190	        applyCameraSource(CAMERA_SOURCES.PI, CAMERA_STATUS_MESSAGES.PI_CONNECTED);
191	        changeScanState("SYSTEM_ACTIVE");
192	      } else {
193	        applyCameraSource(CAMERA_SOURCES.WEBCAM, CAMERA_STATUS_MESSAGES.PI_UNAVAILABLE);
194	        await startCCTV();
195	      }
196	    } else {
197	      applyCameraSource(CAMERA_SOURCES.WEBCAM, CAMERA_STATUS_MESSAGES.WEBCAM_ACTIVE);
198	      await startCCTV();
199	    }
200	  };
201	
202	  const startCCTV = async () => {
203	    // Guard: browser without camera API (insecure context / no webcam support)
204	    if (!navigator.mediaDevices?.getUserMedia) {
205	      changeScanState("HARDWARE_ERR");
206	      return;
207	    }
208	    try {
209	      const stream = await navigator.mediaDevices.getUserMedia({
210	        video: {
211	          width: { ideal: 640 },
212	          height: { ideal: 480 },
213	          frameRate: { ideal: 15, max: 20 },
214	          facingMode: "user"
215	        }
216	      });
217	      if (videoRef.current) {
218	        videoRef.current.srcObject = stream;
219	        videoRef.current.onloadedmetadata = () => {
220	          videoRef.current.play().catch(() => changeScanState("HARDWARE_ERR"));
221	        };
222	      }
223	      changeScanState("SYSTEM_ACTIVE");
224	    } catch (err) {
225	      // Permission denied, no device, or device busy - surface it instead of a black feed
226	      console.error("CCTV camera unavailable:", err);
227	      changeScanState("HARDWARE_ERR");
228	    }
229	  };
230	
231	  const stopCCTV = () => {
232	    if (videoRef.current?.srcObject) {
233	      videoRef.current.srcObject.getTracks().forEach(track => track.stop());
234	    }
235	  };
236	
237	  const playFeedback = (type) => {
238	    const audioPath = type === 'success' ? '/sounds/success.mp3' : '/sounds/denied.mp3';
239	    const audio = new Audio(audioPath);
240	    audio.volume = 0.4;
241	    audio.play().catch(() => console.log("Audio waiting for user gesture"));
242	  };
243	
244	  const grantFinalAccess = (verifiedUser) => {
245	    const subject = describeRecognitionSubject(verifiedUser);
246	    playFeedback('success');
247	    changeScanState("SECURE_MATCH");
248	    setIdentifiedUser(subject.identityLabel);
249	    const evaluationResult = verifiedUser._evaluationResult;
250	    setLastDecision({
251	      state: DECISION_STATES.GRANTED,
252	      identityLabel: subject.identityLabel,
253	      confidence: verifiedUser.confidence ?? evaluationResult?.user?.confidence ?? null,
254	      latencyMs: evaluationResult?.timings?.totalRequestMs ?? evaluationResult?.timings?.nodeToAiMs ?? null,
255	      livenessVerified: true,
256	      cameraSourceLabel,
257	      evaluationResult
258	    });
259	    setScanProgress(100);
260	
261	    const currentTimestamp = Date.now();
262	
263	    if (lastLogRef.current.name !== verifiedUser.name || (currentTimestamp - lastLogRef.current.timestamp > 30000)) {
264	      // Local timeline entry ONLY - the persisted safe access log is created by
265	      // the SERVER during the access-event call below, so the browser never
266	      // posts audit rows (no duplicate client+server logs).
267	      const newLog = {
268	        id: `ACC-${Date.now()}`,
269	        // This is a NEW event happening right now - stamping it is correct.
270	        occurredAt: new Date(currentTimestamp).toISOString(),
271	        type: 'Gantry Access',
272	        desc: `Identity & Liveness Verified: ${subject.identityLabel}`,
273	        severity: 'safe',
274	        icon: 'UNLOCK',
275	        personnelName: verifiedUser.name,
276	        role: verifiedUser.role,
277	        confidence: verifiedUser.confidence,
278	        cameraLocation: CAMERA_LOCATION
279	      };
280	
281	      setIncidentLogs(prev => [newLog, ...prev.slice(0, 14)]);
282	      lastLogRef.current = { name: verifiedUser.name, timestamp: currentTimestamp };
283	
284	      // Server-owned audit: records the deduplicated safe access log WITHOUT
285	      // touching attendance (no clock-in/out from V-Patrol). Non-fatal for the UI.
286	      axios.post(ACCESS_EVENT_URL, {
287	        userId: verifiedUser.id,
288	        cameraLocation: CAMERA_LOCATION
289	      }, { headers: { Authorization: `Bearer ${token}` } })
290	        .catch(e => console.log("Access-event sync failed", e));
291	    }
292	
293	    setTimeout(() => { resetScanner(); }, 3500);
294	  };
295	
296	  // Capture one frame from the active camera source onto the hidden canvas
297	  // and return it as a compressed JPEG data URL for the recognition API.
298	  const captureFrameBase64 = async () => {
299	    const canvas = canvasRef.current;
300	    if (!canvas) return null;
301	    const context = canvas.getContext('2d');
302	    const MAX_WIDTH = CAPTURE_MAX_WIDTH;
303	
304	    if (cameraSourceRef.current === CAMERA_SOURCES.PI) {
305	      let bitmap;
306	      try {
307	        bitmap = await fetchPiSnapshotBitmap();
308	        piFailStreakRef.current = 0;
309	      } catch {
310	        // Pi snapshot failed mid-session - after 3 misses, fall back to webcam
311	        piFailStreakRef.current += 1;
312	        if (piFailStreakRef.current >= 3) {
313	          applyCameraSource(CAMERA_SOURCES.WEBCAM, CAMERA_STATUS_MESSAGES.PI_UNAVAILABLE);
314	          await startCCTV();
315	        }
316	        return null;
317	      }
318	      const scale = Math.min(1, MAX_WIDTH / bitmap.width);
319	      canvas.width = Math.round(bitmap.width * scale);
320	      canvas.height = Math.round(bitmap.height * scale);
321	      context.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
322	      bitmap.close?.();
323	      return canvas.toDataURL('image/jpeg', 0.3);
324	    }
325	
326	    const video = videoRef.current;
327	    if (!video || video.videoWidth === 0) return null;
328	    const scaleDownRatio = MAX_WIDTH / video.videoWidth;
329	    canvas.width = MAX_WIDTH;
330	    canvas.height = video.videoHeight * scaleDownRatio;
331	    context.drawImage(video, 0, 0, canvas.width, canvas.height);
332	    return canvas.toDataURL('image/jpeg', 0.3);
333	  };
334	
335	  const performLiveScan = async () => {
336	    const gate = scanGateRef.current;
337	    // No overlapping requests; short backoff after a recognition-service failure.
338	    if (!gate.canScan()) return;
339	
340	    const canvas = canvasRef.current;
341	    if (!canvas) return;
342	    if (scanStatusRef.current === "SECURE_MATCH" || scanStatusRef.current === "UNKNOWN_QUERY") return;
343	
344	    gate.begin();
345	    const totalTimer = startTimer();
346	
347	    try {
348	      const captureTimer = startTimer();
349	      const imageBase64 = await captureFrameBase64();
350	      const captureMs = captureTimer();
351	      if (!imageBase64) return;
352	
353	      if (scanModeRef.current === 'evaluation') {
354	        const cycleId = lastRecordedScanRef.current || `EVAL-${Date.now()}-${Math.random().toString(36).slice(2)}`;
355	        const res = await axios.post(EVALUATE_URL, { image: imageBase64 }, { headers: { Authorization: `Bearer ${token}` } });
356	        const draft = buildEvaluationDraftFromRecognition({ result: res.data, labelMap: loadLabelMap(), source: 'Live', origin: 'V-Patrol' });
357	        if (draft.detectionOutcome === DETECTION_OUTCOMES.NO_FACE) {
358	          setLastDecision({ state: DECISION_STATES.NO_FACE, cameraSourceLabel, evaluationResult: res.data });
359	          return;
360	        }
361	        const config = evaluationConfigRef.current;
362	        if (config.autoRecord && config.actualLabel && !lastRecordedScanRef.current && !draft.needsMapping) {
363	          lastRecordedScanRef.current = cycleId;
364	          const record = saveEvaluationRecordFromDraft(draft, { actualLabel: config.actualLabel, condition: config.condition });
365	          saveRecords([record, ...loadRecords()]);
366	          notifyEvaluationRecordsUpdated({ origin: 'V-Patrol' });
367	          setLastDecision({ state: res.data.policyDecision === 'GRANTED' ? DECISION_STATES.GRANTED : DECISION_STATES.UNKNOWN, identityLabel: draft.predictedLabel, confidence: draft.confidence, latencyMs: draft.latencyMs, cameraSourceLabel, evaluationResult: res.data, evaluationMessage: 'Live evaluation sample recorded' });
368	          setTimeout(() => { lastRecordedScanRef.current = null; }, 3500);
369	        }
370	        return;
371	      }
372	
373	      const apiTimer = startTimer();
374	      const res = await axios.post(RECOGNIZE_URL,
375	        { image: imageBase64, cameraLocation: CAMERA_LOCATION },
376	        { headers: { Authorization: `Bearer ${token}` } }
377	      );
378	      logScanTimings({
379	        captureMs,
380	        apiMs: apiTimer(),
381	        totalMs: totalTimer(),
382	        serverTimings: res.data?.timings
383	      });
384	      setServiceNotice('');
385	
386	      if (scanStatusRef.current === "SECURE_MATCH" || scanStatusRef.current === "UNKNOWN_QUERY") {
387	        return;
388	      }
389	
390	      if (res.data && Array.isArray(res.data.box) && res.data.box.length === 4) {
391	        // FastAPI contract: box is exactly [x, y, width, height] in pixels of
392	        // the captured frame. Direct mapping (no corner-order guessing),
393	        // clamped to the frame, projected onto the contain-fit preview.
394	        const frame = { width: canvas.width, height: canvas.height };
395	        const containerEl = containerRef.current;
396	        const container = containerEl
397	          ? { width: containerEl.clientWidth, height: containerEl.clientHeight }
398	          : frame;
399	        const { width: boxWidth } = clampBoxToFrame(res.data.box, frame.width, frame.height);
400	        const targetBox = faceBoxStyle(res.data.box, frame, container, 'contain');
401	
402	        // Calculate proximity based on the compressed canvas width
403	        const faceProximityPercentage = (boxWidth / canvas.width) * 100;
404	        const livenessRatio = res.data.liveness_ratio || 0.5;
405	
406	        if (faceProximityPercentage < 5 && scanStatusRef.current !== "LIVENESS_CHECK") {
407	          if (scanStatusRef.current === "SYSTEM_ACTIVE" || scanStatusRef.current === "PRESENCE_DETECTED") {
408	            changeScanState("PRESENCE_DETECTED");
409	            setFaceBox(null);
410	            setScanProgress(0);
411	          }
412	          return;
413	        }
414	
415	        if (scanStatusRef.current === "LIVENESS_CHECK") {
416	          setFaceBox(targetBox);
417	          const currentRecognitionUser = res.data.user;
418	          if (!candidateUserRef.current || !currentRecognitionUser || candidateUserRef.current.id !== currentRecognitionUser.id) {
419	            resetScanner();
420	            return;
421	          }
422	
423	          if (livenessRatio < 0.45 || livenessRatio > 0.55) {
424	            grantFinalAccess(candidateUserRef.current);
425	          }
426	          return;
427	        }
428	
429	        if (scanStatusRef.current === "SYSTEM_ACTIVE" || scanStatusRef.current === "PRESENCE_DETECTED") {
430	          changeScanState("TARGET_LOCKING");
431	          setFaceBox(targetBox);
432	          setScanProgress(12);
433	
434	          let progress = 12;
435	          progressIntervalRef.current = setInterval(() => {
436	            progress += Math.floor(Math.random() * 14) + 4;
437	            if (progress >= 96) {
438	              setScanProgress(96);
439	              clearInterval(progressIntervalRef.current);
440	            } else {
441	              setScanProgress(progress);
442	            }
443	          }, 120);
444	
445	          lockTimerRef.current = setTimeout(() => {
446	            clearInterval(progressIntervalRef.current);
447	
448	            const currentTimestamp = Date.now();
449	            const logTimeStr = new Date().toLocaleTimeString('en-SG', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true });
450	
451	            const recognizedUser = res.data.user;
452	            if (recognizedUser && recognizedUser.status === RECOGNITION_STATUS.AUTHORIZED) {
453	              candidateUserRef.current = { ...recognizedUser, _evaluationResult: res.data };
454	              changeScanState("LIVENESS_CHECK");
455	            } else {
456	              // Suspended or unknown - the Node backend has already written the
457	              // deduplicated SecurityLog; the client only updates its local timeline.
458	              const isSuspended = recognizedUser && recognizedUser.status === RECOGNITION_STATUS.SUSPENDED;
459	              const subject = describeRecognitionSubject(recognizedUser);
460	              const latencyMs = res.data?.timings?.totalRequestMs ?? res.data?.timings?.nodeToAiMs ?? null;
461	
462	              playFeedback('denied');
463	              changeScanState("UNKNOWN_QUERY");
464	              setIdentifiedUser(isSuspended ? `${subject.identityLabel} - SUSPENDED` : "UNKNOWN PERSONNEL");
465	              setScanProgress(0);
466	              setLastDecision({
467	                state: isSuspended ? DECISION_STATES.SUSPENDED : DECISION_STATES.UNKNOWN,
468	                identityLabel: isSuspended ? subject.identityLabel : 'Unknown Person',
469	                confidence: recognizedUser?.confidence ?? null,
470	                latencyMs,
471	                cameraSourceLabel,
472	                evaluationResult: res.data
473	              });
474	
475	              const dedupName = isSuspended ? recognizedUser.name : "UNKNOWN";
476	              if (lastLogRef.current.name !== dedupName || (currentTimestamp - lastLogRef.current.timestamp > 10000)) {
477	                const newLog = {
478	                  id: `SEC-${Date.now()}`,
479	                  // New event happening right now - stamped at detection time.
480	                  occurredAt: new Date(currentTimestamp).toISOString(),
481	                  time: logTimeStr,
482	                  type: isSuspended ? 'Suspended Access Attempt' : 'Intrusion Alert',
483	                  desc: isSuspended
484	                    ? `Suspended account denied at gantry: ${subject.identityLabel}.`
485	                    : 'Unregistered personnel detected at gantry.',
486	                  severity: 'critical',
487	                  icon: isSuspended ? 'DENIED' : 'ALERT',
488	                  personnelName: isSuspended ? recognizedUser.name : null,
489	                  role: isSuspended ? recognizedUser.role : null,
490	                  confidence: recognizedUser ? recognizedUser.confidence : null,
491	                  cameraLocation: CAMERA_LOCATION
492	                };
493	
494	                setIncidentLogs(prev => [newLog, ...prev.slice(0, 14)]);
495	                lastLogRef.current = { name: dedupName, timestamp: currentTimestamp };
496	              }
497	
498	              setTimeout(() => { resetScanner(); }, 3500);
499	            }
500	          }, TARGET_LOCK_MS);
501	
502	        } else if (scanStatusRef.current === "TARGET_LOCKING") {
503	          setFaceBox(targetBox);
504	        }
505	
506	      } else {
507	        if (scanStatusRef.current !== "LIVENESS_CHECK" && scanStatusRef.current !== "TARGET_LOCKING") {
508	          setLastDecision({
509	            state: DECISION_STATES.NO_FACE,
510	            cameraSourceLabel,
511	            evaluationResult: res.data
512	          });
513	          resetScanner();
514	        }
515	      }
516	    } catch (err) {
517	      // Node/FastAPI unavailable - back off instead of flooding the endpoint.
518	      // The camera preview keeps running; webcam fallback is ONLY for Pi failure.
519	      console.error("AI Command Loop Fault:", err);
520	      scanGateRef.current.applyBackoff();
521	      setServiceNotice(SERVICE_UNAVAILABLE_MSG);
522	    } finally {
523	      scanGateRef.current.end();
524	    }
525	  };
526	
527	  // Frontend filtering of the loaded timeline records (PoC).
528	  const activeFilters = { dateRange: dateFilter, eventType: eventFilter, search: searchFilter };
529	  const filteredLogs = filterSecurityLogs(incidentLogs, activeFilters);
530	
531	  const resetScanner = () => {
532	    setIdentifiedUser(null);
533	    setFaceBox(null);
