1	import React, { useRef, useState, useEffect } from 'react';
2	import axios from 'axios';
3	import Sidebar from '../components/Sidebar';
4	import { DECISION_STATES } from '../components/RecognitionDecisionCard';
5	import EvaluationRecorderModal from '../components/EvaluationRecorderModal';
6	import LiveConfusionMatrixPanel from '../components/LiveConfusionMatrixPanel';
7	import useEvaluationParticipants from '../hooks/useEvaluationParticipants';
8	import '../css/Dashboard.css';
9	import '../css/VPatrol.css'; // Reusing the high-tech tracking box and HUD dashboard styles
10	import {
11	  PI_CAMERA_STREAM_URL,
12	  CAMERA_SOURCES,
13	  CAMERA_STATUS_MESSAGES,
14	  isPiCameraReachable,
15	  fetchPiSnapshotBitmap,
16	} from '../constants/piCamera';
17	import { API_BASE_URL } from '../constants/api';
18	import { clampBoxToFrame, faceBoxStyle } from '../constants/faceBox';
19	import { describeRecognitionSubject, RECOGNITION_STATUS } from '../constants/recognition';
20	import { loadLabelMap, buildEvaluationDraftFromRecognition, loadRecords, saveRecords, saveEvaluationRecordFromDraft, notifyEvaluationRecordsUpdated, DETECTION_OUTCOMES } from '../constants/evaluation';
21	import {
22	  SCAN_INTERVAL_MS,
23	  TARGET_LOCK_MS,
24	  CAPTURE_MAX_WIDTH,
25	  SERVICE_UNAVAILABLE_MSG,
26	  createScanGate,
27	  startTimer,
28	  logScanTimings,
29	} from '../constants/scanControl';
30	
31	const MATRIX_ORIGIN = 'Gate Scanner';
32	
33	const GateScanner = () => {
34	  const videoRef = useRef(null);
35	  const canvasRef = useRef(null);
36	  const containerRef = useRef(null); // preview container, for face-box projection
37	
38	  const [scanStatus, setScanStatus] = useState("SYSTEM_ACTIVE");
39	  const [displayMessage, setDisplayMessage] = useState("PLACE FACE IN VIEWPORT");
40	  const [faceBox, setFaceBox] = useState(null);
41	  const [scanProgress, setScanProgress] = useState(0);
42	
43	  // Camera source: Raspberry Pi Gate Camera is primary, laptop webcam is fallback
44	  const [cameraSource, setCameraSource] = useState(CAMERA_SOURCES.PI);
45	  const [cameraStatusMsg, setCameraStatusMsg] = useState("Connecting to Pi Gate Camera...");
46	
47	  // Last gate decision - safe display fields only (never biometric data).
48	  const [lastDecision, setLastDecision] = useState(null);
49	  const [evalModal, setEvalModal] = useState({ open: false, draft: null });
50	  const [scanMode, setScanMode] = useState('operational');
51	  const [evaluationConfig, setEvaluationConfig] = useState({ actualLabel: '', condition: 'Front', autoRecord: true });
52	  const { participants, labels: participantLabels, loading: participantsLoading, error: participantsError } = useEvaluationParticipants();
53	  const scanModeRef = useRef('operational');
54	  const evaluationConfigRef = useRef({ actualLabel: '', condition: 'Front', autoRecord: true });
55	  const lastRecordedScanRef = useRef(null);
56	  // Switching modes clears the previous decision so the evaluation accordion
57	  // only ever shows results produced in Live Evaluation Mode.
58	  const updateScanMode = (mode) => { setScanMode(mode); scanModeRef.current = mode; lastRecordedScanRef.current = null; setLastDecision(null); };
59	  const updateEvaluationConfig = (next) => { setEvaluationConfig(next); evaluationConfigRef.current = next; };
60	  const cameraSourceRef = useRef(CAMERA_SOURCES.PI);
61	  const piFailStreakRef = useRef(0);
62	
63	  const scanStatusRef = useRef("SYSTEM_ACTIVE");
64	  const lockTimerRef = useRef(null);
65	  const progressIntervalRef = useRef(null);
66	  const candidateUserRef = useRef(null);
67	  // No-overlap + AI-error-backoff guard for the scan loop.
68	  const scanGateRef = useRef(createScanGate());
69	
70	  const token = localStorage.getItem("accessToken");
71	  // All recognition traffic goes through the Node backend - never FastAPI directly.
72	  const ATTENDANCE_SCAN_URL = `${API_BASE_URL}/api/attendance/scan`;
73	  const RECOGNIZE_URL = `${API_BASE_URL}/api/facial-recognition/recognize`;
74	  const EVALUATE_URL = `${API_BASE_URL}/api/facial-recognition/evaluate`;
75	  const CAMERA_LOCATION = "South Entrance Turnstile";
76	
77	  const cameraSourceLabel = cameraSource === CAMERA_SOURCES.PI ? 'Raspberry Pi Gate Camera' : 'Laptop Webcam';
78	
79	  // Recording ground truth only stores one local evaluation record - it never
80	  // re-runs recognition and never creates Attendance or SecurityLogs.
81	  const openEvaluationRecorder = (result) => {
82	    const draft = buildEvaluationDraftFromRecognition({ result, labelMap: loadLabelMap(), origin: MATRIX_ORIGIN });
83	    setEvalModal({ open: true, draft });
84	  };
85	
86	  const handleEvaluationSaved = () => {
87	    setEvalModal({ open: false, draft: null });
88	    setLastDecision((prev) => prev ? { ...prev, evaluationMessage: 'Live evaluation result recorded' } : prev);
89	  };
90	
91	  const changeScanState = (nextState, message) => {
92	    setScanStatus(nextState);
93	    scanStatusRef.current = nextState;
94	    if (message) setDisplayMessage(message);
95	  };
96	
97	  useEffect(() => {
98	    initCameraSource();
99	    const scanInterval = setInterval(() => performPerimeterScan(), SCAN_INTERVAL_MS);
100	
101	    return () => {
102	      stopGateCamera();
103	      clearInterval(scanInterval);
104	      if (lockTimerRef.current) clearTimeout(lockTimerRef.current);
105	      if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
106	    };
107	  }, []);
108	
109	  const applyCameraSource = (source, statusMsg) => {
110	    cameraSourceRef.current = source;
111	    setCameraSource(source);
112	    setCameraStatusMsg(statusMsg);
113	    piFailStreakRef.current = 0;
114	  };
115	
116	  // Primary source: Raspberry Pi Gate Camera. Probe the snapshot endpoint on
117	  // load; if unreachable, automatically fall back to the laptop webcam.
118	  const initCameraSource = async () => {
119	    const piReachable = await isPiCameraReachable();
120	    if (piReachable) {
121	      stopGateCamera();
122	      applyCameraSource(CAMERA_SOURCES.PI, CAMERA_STATUS_MESSAGES.PI_CONNECTED);
123	      changeScanState("SYSTEM_ACTIVE", "GATE TURNSTILE ONLINE // AWAITING TARGET");
124	    } else {
125	      applyCameraSource(CAMERA_SOURCES.WEBCAM, CAMERA_STATUS_MESSAGES.PI_UNAVAILABLE);
126	      await startGateCamera();
127	    }
128	  };
129	
130	  // Manual camera source switch (Pi Gate Camera / Laptop Webcam)
131	  const selectCameraSource = async (source) => {
132	    if (source === cameraSourceRef.current) return;
133	    if (source === CAMERA_SOURCES.PI) {
134	      const piReachable = await isPiCameraReachable();
135	      if (piReachable) {
136	        stopGateCamera();
137	        applyCameraSource(CAMERA_SOURCES.PI, CAMERA_STATUS_MESSAGES.PI_CONNECTED);
138	      } else {
139	        applyCameraSource(CAMERA_SOURCES.WEBCAM, CAMERA_STATUS_MESSAGES.PI_UNAVAILABLE);
140	        await startGateCamera();
141	      }
142	    } else {
143	      applyCameraSource(CAMERA_SOURCES.WEBCAM, CAMERA_STATUS_MESSAGES.WEBCAM_ACTIVE);
144	      await startGateCamera();
145	    }
146	  };
147	
148	  const startGateCamera = async () => {
149	    if (!navigator.mediaDevices?.getUserMedia) {
150	      changeScanState("HARDWARE_ERR", "NO CAMERA DETECTED ON THIS TERMINAL");
151	      return;
152	    }
153	    try {
154	      const stream = await navigator.mediaDevices.getUserMedia({
155	        video: {
156	          width: { ideal: 640 },
157	          height: { ideal: 480 },
158	          frameRate: { ideal: 15, max: 20 },
159	          facingMode: "user"
160	        },
161	        audio: false
162	      });
163	      if (videoRef.current) {
164	        videoRef.current.srcObject = stream;
165	        videoRef.current.onloadedmetadata = () => {
166	          videoRef.current.play().catch(() => changeScanState("HARDWARE_ERR", "CAMERA STREAM PAUSED"));
167	        };
168	      }
169	      changeScanState("SYSTEM_ACTIVE", "GATE TURNSTILE ONLINE // AWAITING TARGET");
170	    } catch (err) {
171	      changeScanState("HARDWARE_ERR", "HARDWARE FAILURE: CAMERA NOT DETECTED");
172	    }
173	  };
174	
175	  const stopGateCamera = () => {
176	    if (videoRef.current?.srcObject) {
177	      videoRef.current.srcObject.getTracks().forEach(track => track.stop());
178	    }
179	  };
180	
181	  const processAttendanceTransaction = async (verifiedUser) => {
182	    const subject = describeRecognitionSubject(verifiedUser);
183	    changeScanState("AUTHORIZING", "AUTHORISING GATE TRANSACTION");
184	    setScanProgress(100);
185	
186	    const evaluationResult = verifiedUser._evaluationResult;
187	    const confidence = verifiedUser.confidence ?? evaluationResult?.user?.confidence ?? null;
188	    const latencyMs = evaluationResult?.timings?.totalRequestMs ?? evaluationResult?.timings?.nodeToAiMs ?? null;
189	
190	    try {
191	      // Hit the Node.js automatic clock-in/out controller with the
192	      // server-verified unique user ID - never a name.
193	      const res = await axios.post(ATTENDANCE_SCAN_URL, {
194	        userId: verifiedUser.id,
195	        cameraLocation: CAMERA_LOCATION
196	      }, {
197	        headers: { Authorization: `Bearer ${token}` }
198	      });
199	
200	      if (res.status >= 200 && res.status < 300 && res.data && res.data.action) {
201	        changeScanState("SECURE_MATCH", `IDENTITY VERIFIED: ${subject.identityLabel}`);
202	        // Render the exact system response action directly onto the kiosk screen
203	        const actionMessage = res.data.action.replace(/_/g, " ");
204	        setDisplayMessage(`${subject.identityLabel} - ${actionMessage}`);
205	        setLastDecision({
206	          state: DECISION_STATES.GRANTED,
207	          identityLabel: subject.identityLabel,
208	          confidence,
209	          latencyMs,
210	          livenessVerified: true,
211	          cameraSourceLabel,
212	          evaluationResult
213	        });
214	      }
215	    } catch (err) {
216	      console.error("Attendance Sync Failed:", err);
217	      setDisplayMessage("GATE TRANSACTION ROUTING FAULT");
218	      setLastDecision({
219	        state: DECISION_STATES.UNKNOWN,
220	        identityLabel: subject.identityLabel,
221	        confidence,
222	        latencyMs,
223	        livenessVerified: true,
224	        cameraSourceLabel,
225	        actionOverride: 'Gate authorisation failed - access remains locked.',
226	        evaluationResult
227	      });
228	    }
229	
230	    setTimeout(() => { resetTurnstileKiosk(); }, 4000);
231	  };
232	
233	  // Capture one frame from the active camera source onto the hidden canvas
234	  // and return it as a compressed JPEG data URL for the recognition API.
235	  const captureFrameBase64 = async () => {
236	    const canvas = canvasRef.current;
237	    if (!canvas) return null;
238	    const context = canvas.getContext('2d');
239	    const maxWidth = CAPTURE_MAX_WIDTH;
240	
241	    if (cameraSourceRef.current === CAMERA_SOURCES.PI) {
242	      let bitmap;
243	      try {
244	        bitmap = await fetchPiSnapshotBitmap();
245	        piFailStreakRef.current = 0;
246	      } catch {
247	        // Pi snapshot failed mid-session - after 3 misses, fall back to webcam
248	        piFailStreakRef.current += 1;
249	        if (piFailStreakRef.current >= 3) {
250	          applyCameraSource(CAMERA_SOURCES.WEBCAM, CAMERA_STATUS_MESSAGES.PI_UNAVAILABLE);
251	          await startGateCamera();
252	        }
253	        return null;
254	      }
255	      const scale = Math.min(1, maxWidth / bitmap.width);
256	      canvas.width = Math.round(bitmap.width * scale);
257	      canvas.height = Math.round(bitmap.height * scale);
258	      context.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
259	      bitmap.close?.();
260	      return canvas.toDataURL('image/jpeg', 0.3);
261	    }
262	
263	    const video = videoRef.current;
264	    if (!video || video.videoWidth === 0) return null;
265	    const scale = Math.min(1, maxWidth / video.videoWidth);
266	    canvas.width = Math.round(video.videoWidth * scale);
267	    canvas.height = Math.round(video.videoHeight * scale);
268	    context.drawImage(video, 0, 0, canvas.width, canvas.height);
269	    return canvas.toDataURL('image/jpeg', 0.3);
270	  };
271	
272	  const performPerimeterScan = async () => {
273	    const gate = scanGateRef.current;
274	    // No overlapping requests; short backoff after a recognition-service failure.
275	    if (!gate.canScan()) return;
276	
277	    const canvas = canvasRef.current;
278	    if (!canvas) return;
279	    if (scanStatusRef.current === "SECURE_MATCH" || scanStatusRef.current === "UNKNOWN_QUERY") return;
280	
281	    gate.begin();
282	    const totalTimer = startTimer();
283	
284	    try {
285	      const captureTimer = startTimer();
286	      const imageBase64 = await captureFrameBase64();
287	      const captureMs = captureTimer();
288	      if (!imageBase64) return;
289	
290	      if (scanModeRef.current === 'evaluation') {
291	        const cycleId = lastRecordedScanRef.current || `EVAL-${Date.now()}-${Math.random().toString(36).slice(2)}`;
292	        const res = await axios.post(EVALUATE_URL, { image: imageBase64 }, { headers: { Authorization: `Bearer ${token}` } });
293	        const draft = buildEvaluationDraftFromRecognition({ result: res.data, labelMap: loadLabelMap(), source: 'Live', origin: 'Gate Scanner' });
294	        if (draft.detectionOutcome === DETECTION_OUTCOMES.NO_FACE) {
295	          setLastDecision({ state: DECISION_STATES.NO_FACE, cameraSourceLabel, evaluationResult: res.data });
296	          return;
297	        }
298	        const config = evaluationConfigRef.current;
299	        if (config.autoRecord && config.actualLabel && !lastRecordedScanRef.current && !draft.needsMapping) {
300	          lastRecordedScanRef.current = cycleId;
301	          const record = saveEvaluationRecordFromDraft(draft, { actualLabel: config.actualLabel, condition: config.condition });
302	          saveRecords([record, ...loadRecords()]);
303	          notifyEvaluationRecordsUpdated({ origin: 'Gate Scanner' });
304	          setLastDecision({ state: res.data.policyDecision === 'GRANTED' ? DECISION_STATES.GRANTED : DECISION_STATES.UNKNOWN, identityLabel: draft.predictedLabel, confidence: draft.confidence, latencyMs: draft.latencyMs, cameraSourceLabel, evaluationResult: res.data, evaluationMessage: 'Live evaluation sample recorded' });
305	          setTimeout(() => { lastRecordedScanRef.current = null; }, 3500);
306	        }
307	        return;
308	      }
309	
310	      const apiTimer = startTimer();
311	      const res = await axios.post(RECOGNIZE_URL, {
312	        image: imageBase64,
313	        cameraLocation: CAMERA_LOCATION
314	      }, {
315	        headers: { Authorization: `Bearer ${token}` }
316	      });
317	      logScanTimings({
318	        captureMs,
319	        apiMs: apiTimer(),
320	        totalMs: totalTimer(),
321	        serverTimings: res.data?.timings
322	      });
323	
324	      if (scanStatusRef.current === "SECURE_MATCH" || scanStatusRef.current === "UNKNOWN_QUERY") return;
325	
326	      if (res.data && Array.isArray(res.data.box) && res.data.box.length === 4) {
327	        // FastAPI contract: box is exactly [x, y, width, height] in pixels of
328	        // the captured frame. Direct mapping (no corner-order guessing),
329	        // clamped to the frame, projected onto the contain-fit preview.
330	        const frame = { width: canvas.width, height: canvas.height };
331	        const containerEl = containerRef.current;
332	        const container = containerEl
333	          ? { width: containerEl.clientWidth, height: containerEl.clientHeight }
334	          : frame;
335	        const { width: boxWidth } = clampBoxToFrame(res.data.box, frame.width, frame.height);
336	        const targetBox = faceBoxStyle(res.data.box, frame, container, 'contain');
337	
338	        const faceProximityPercentage = (boxWidth / canvas.width) * 100;
339	        const livenessRatio = res.data.liveness_ratio || 0.5;
340	
341	        if (faceProximityPercentage < 8 && scanStatusRef.current !== "LIVENESS_CHECK") {
342	          changeScanState("PRESENCE_DETECTED", "TARGET DETECTED // MOVE CLOSER");
343	          setFaceBox(null);
344	          return;
345	        }
346	
347	        // LIVENESS CHECK: Wait for head swing rotation
348	        if (scanStatusRef.current === "LIVENESS_CHECK") {
349	          setFaceBox(targetBox);
350	          const currentRecognitionUser = res.data.user;
351	          if (!candidateUserRef.current || !currentRecognitionUser || candidateUserRef.current.id !== currentRecognitionUser.id) {
352	            resetTurnstileKiosk();
353	            return;
354	          }
355	          if (livenessRatio < 0.35 || livenessRatio > 0.65) {
356	            await processAttendanceTransaction(candidateUserRef.current);
357	          }
358	          return;
359	        }
360	
361	        // TARGET LOCKING SEQUENCE
362	        if (scanStatusRef.current === "SYSTEM_ACTIVE" || scanStatusRef.current === "PRESENCE_DETECTED") {
363	          changeScanState("TARGET_LOCKING", "LOCKING BIOMETRIC VECTORS...");
364	          setFaceBox(targetBox);
365	          setScanProgress(12);
366	
367	          let progress = 12;
368	          progressIntervalRef.current = setInterval(() => {
369	            progress += Math.floor(Math.random() * 14) + 4;
370	            if (progress >= 96) { setScanProgress(96); clearInterval(progressIntervalRef.current); }
371	            else { setScanProgress(progress); }
372	          }, 120);
373	
374	          lockTimerRef.current = setTimeout(() => {
375	            clearInterval(progressIntervalRef.current);
376	
377	            const recognizedUser = res.data.user;
378	            const confidence = recognizedUser?.confidence ?? null;
379	            const latencyMs = res.data?.timings?.totalRequestMs ?? res.data?.timings?.nodeToAiMs ?? null;
380	
381	            if (recognizedUser && recognizedUser.status === RECOGNITION_STATUS.AUTHORIZED) {
382	              candidateUserRef.current = { ...recognizedUser, _evaluationResult: res.data };
383	              changeScanState("LIVENESS_CHECK", "VERIFYING LIVENESS: TURN HEAD SLIGHTLY");
384	            } else if (recognizedUser && recognizedUser.status === RECOGNITION_STATUS.SUSPENDED) {
385	              // Server already denied access and wrote the security log.
386	              const subject = describeRecognitionSubject(recognizedUser);
387	              changeScanState("UNKNOWN_QUERY", `${subject.identityLabel} - ${subject.accessLabel}`);
388	              setLastDecision({
389	                state: DECISION_STATES.SUSPENDED,
390	                identityLabel: subject.identityLabel,
391	                confidence,
392	                latencyMs,
393	                cameraSourceLabel,
394	                evaluationResult: res.data
395	              });
396	              setScanProgress(0);
397	              setTimeout(() => { resetTurnstileKiosk(); }, 3500);
398	            } else {
399	              // Unknown person - server already wrote the intrusion log.
400	              changeScanState("UNKNOWN_QUERY", "PERIMETER BREACH: ACCESS DENIED");
401	              setLastDecision({
402	                state: DECISION_STATES.UNKNOWN,
403	                identityLabel: describeRecognitionSubject(recognizedUser).identityLabel,
404	                confidence,
405	                latencyMs,
406	                cameraSourceLabel,
407	                evaluationResult: res.data
408	              });
409	              setScanProgress(0);
410	              setTimeout(() => { resetTurnstileKiosk(); }, 3500);
411	            }
412	          }, TARGET_LOCK_MS);
413	        } else if (scanStatusRef.current === "TARGET_LOCKING") {
414	          setFaceBox(targetBox);
415	        }
416	      } else {
417	        if (scanStatusRef.current !== "LIVENESS_CHECK" && scanStatusRef.current !== "TARGET_LOCKING") {
418	          setLastDecision({
419	            state: DECISION_STATES.NO_FACE,
420	            cameraSourceLabel,
421	            evaluationResult: res.data
422	          });
423	          resetTurnstileKiosk();
424	        }
425	      }
426	    } catch (err) {
427	      // Node/FastAPI unavailable - back off instead of flooding the endpoint.
428	      // The camera preview keeps running; webcam fallback is ONLY for Pi failure.
429	      console.error("Gate AI Link Fault:", err);
430	      gate.applyBackoff();
431	      setDisplayMessage(SERVICE_UNAVAILABLE_MSG);
432	    } finally {
433	      gate.end();
434	    }
435	  };
436	
437	  const resetTurnstileKiosk = () => {
438	    setFaceBox(null);
439	    setScanProgress(0);
440	    candidateUserRef.current = null;
441	    changeScanState("SYSTEM_ACTIVE", "GATE TURNSTILE ONLINE // AWAITING TARGET");
442	  };
443	
444	  return (
445	    <div className="dashboard-layout">
446	      <Sidebar />
447	      <main className="dashboard-main gate-main">
448	        <header className="dashboard-header">
449	          <div className="header-titles">
450	            <h1>Perimeter Gate Attendance Terminal</h1>
451	            <p>Main Facility Entrance Turnstile Facial Recognition Interface</p>
452	          </div>
453	        </header>
454	
455	        <div className="camera-source-bar" style={{ display: 'flex', alignItems: 'center', gap: '12px', flexWrap: 'wrap', marginBottom: '12px' }}>
456	          <span style={{ color: '#94a3b8', fontSize: '0.85rem', fontWeight: 600 }}>Camera Source:</span>
457	          <button
458	            onClick={() => selectCameraSource(CAMERA_SOURCES.PI)}
459	            style={{
460	              padding: '6px 14px', borderRadius: 8, cursor: 'pointer', fontSize: '0.85rem',
461	              border: cameraSource === CAMERA_SOURCES.PI ? '1px solid #3b82f6' : '1px solid #334155',
462	              background: cameraSource === CAMERA_SOURCES.PI ? '#1d4ed8' : '#1e293b', color: '#e2e8f0'
463	            }}
464	          >
465	            Raspberry Pi Gate Camera
466	          </button>
467	          <button
468	            onClick={() => selectCameraSource(CAMERA_SOURCES.WEBCAM)}
469	            style={{
470	              padding: '6px 14px', borderRadius: 8, cursor: 'pointer', fontSize: '0.85rem',
471	              border: cameraSource === CAMERA_SOURCES.WEBCAM ? '1px solid #3b82f6' : '1px solid #334155',
472	              background: cameraSource === CAMERA_SOURCES.WEBCAM ? '#1d4ed8' : '#1e293b', color: '#e2e8f0'
473	            }}
474	          >
475	            Laptop Webcam
476	          </button>
477	          <span style={{ color: '#38bdf8', fontSize: '0.82rem' }}>{cameraStatusMsg}</span>
478	        </div>
479	
480	        <section className="evaluation-mode-controls" aria-label="Scanner mode">
481	          <div className="scan-mode-selector">
482	            <button type="button" aria-pressed={scanMode === 'operational'} className={scanMode === 'operational' ? 'active' : ''} onClick={() => updateScanMode('operational')}>Operational Mode</button>
483	            <button type="button" aria-pressed={scanMode === 'evaluation'} className={scanMode === 'evaluation' ? 'active' : ''} onClick={() => updateScanMode('evaluation')}>Live Evaluation Mode</button>
484	          </div>
485	        </section>
486	
487	        <EvaluationRecorderModal
488	          open={evalModal.open}
489	          draft={evalModal.draft}
490	          onSaved={handleEvaluationSaved}
491	          onClose={() => setEvalModal({ open: false, draft: null })}
492	        />
493	
494	        <div className="vpatrol-grid" style={{ gridTemplateColumns: '1fr' }}>
495	          <div className="vpatrol-card monitor-section">
496	            <div ref={containerRef} className={`cctv-container state-theme-${scanStatus.toLowerCase()}`} style={{ width: '100%', height: '100%' }}>
497	              {cameraSource === CAMERA_SOURCES.PI && (
498	                <img
499	                  src={PI_CAMERA_STREAM_URL}
500	                  alt="Raspberry Pi gate camera live preview"
501	                  className="video-feed"
502	                />
503	              )}
504	              <video
505	                ref={videoRef}
506	                autoPlay
507	                playsInline
508	                muted
509	                className="video-feed"
510	                style={cameraSource === CAMERA_SOURCES.PI ? { display: 'none' } : undefined}
511	              />
512	              <canvas ref={canvasRef} style={{ display: 'none' }} />
513	
514	              {faceBox && (
515	                <div className={`face-tracking-box state-${scanStatus.toLowerCase()}`} style={{ top: faceBox.top, left: faceBox.left, width: faceBox.width, height: faceBox.height }}>
516	                  <div className="corner-bracket top-left"></div>
517	                  <div className="corner-bracket top-right"></div>
518	                  <div className="corner-bracket bottom-left"></div>
519	                  <div className="corner-bracket bottom-right"></div>
520	                  {scanStatus === "TARGET_LOCKING" && <div className="matrix-scan-line"></div>}
521	
522	                  <div className="box-identity-panel">
523	                    <span className="access-status-label">
524	                      {scanStatus === "TARGET_LOCKING" && `ANALYZING: ${scanProgress}%`}
525	                      {scanStatus === "LIVENESS_CHECK" && "ANTI-SPOOF ACTIVE"}
