307	                  ) : filteredUsers.map((u) => {
308	                    const isSelf = String(u.id) === String(currentUserId);
309	                    return (
310	                      <tr key={u.id} className={u.isActive === false ? 'row-suspended' : ''}>
311	                        <td className="user-name-cell" data-label="Personnel">
312	                          <div className="user-identity">
313	                            <div className="user-avatar-small">{u.name?.charAt(0).toUpperCase()}</div>
314	                            <span className="user-name-text">{u.name} {isSelf && <span className="self-tag">(You)</span>}</span>
315	                          </div>
316	                        </td>
317	                        <td data-label="Role">{renderRoleBadge(u.role)}</td>
318	                        <td className="access-cell email-cell" data-label="Email" title={u.email}>{u.email}</td>
319	                        <td data-label="Status">{renderStatusBadge(u)}</td>
320	                        <td data-label="Face ID">
321	                          <span className={`presence-tag ${u.isEnrolled ? 'on-site' : 'off-site'}`} title={u.isEnrolled ? 'A protected biometric template is enrolled' : 'No Face ID enrolled yet'}>
322	                            {u.isEnrolled ? <><SafeMuiIcon icon={CheckCircleIcon} fontSize="small" aria-hidden="true" /> Enrolled</> : <><SafeMuiIcon icon={CancelIcon} fontSize="small" aria-hidden="true" /> Not Enrolled</>}
323	                          </span>
324	                        </td>
325	                        <td className="time-cell" data-label="Joined">{new Date(u.createdAt).toLocaleDateString('en-SG')}</td>
326	                        <td className="actions-cell" data-label="Actions">
327	                          {/* Face ID enrol/re-enrol intentionally lives in the
328	                              enrolment flow (first-time) and Settings (self
329	                              re-enrolment) — never as a row action here. */}
330	                          <div className="action-button-group" aria-label={`Actions for ${u.name}`}>
331	                            <button className="action-btn action-neutral" onClick={() => navigate(`/user-logs/${u.id}`)}>
332	                              <SafeMuiIcon icon={VisibilityIcon} fontSize="inherit" aria-hidden="true" />
333	                              View Logs
334	                            </button>
335	                            <button className={`action-btn ${u.isActive === false ? 'action-restore' : 'action-warning'} ${isSelf ? 'disabled-action' : ''}`} onClick={() => !isSelf && openModal(u, 'suspend')} disabled={isSelf}>
336	                              <SafeMuiIcon icon={u.isActive === false ? CheckCircleIcon : BlockIcon} fontSize="inherit" aria-hidden="true" />
337	                              {u.isActive === false ? 'Reactivate' : 'Suspend'}
338	                            </button>
339	                            <button className={`action-btn action-danger ${isSelf ? 'disabled-action' : ''}`} onClick={() => !isSelf && openModal(u, 'delete')} disabled={isSelf}>
340	                              <SafeMuiIcon icon={DeleteOutlineIcon} fontSize="inherit" aria-hidden="true" />
341	                              Delete
342	                            </button>
343	                          </div>
344	                        </td>
345	                      </tr>
346	                    );
347	                  })}
348	                </tbody>
349	              </table>
350	            )}
351	          </div>
352	        </div>
353	      </main>
354	    </div>
355	  );
356	};
357	
358	export default Users;
