42	    flex: 1;
43	    min-height: 0;
44	    display: flex;              /* flex row: height-driven sizing avoids grid/aspect-ratio conflicts */
45	    flex-direction: row;
46	    align-items: flex-start;
47	    gap: 24px;                  /* more breathing room between camera and timeline */
48	}
