59	.vpatrol-main .vpatrol-card.monitor-section {
60	    flex: none;
61	    width: auto;
62	    height: 100%;
63	    max-height: 600px;
64	    aspect-ratio: 1 / 1;
65	    margin: 0;
66	}
67	
