file.content:
.users-header {
    align-items: center;
}

.user-summary-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(140px, 1fr));
    gap: 12px;
    margin-bottom: 14px;
}

.user-summary-grid > div {
    background: #1e293b;
    border: 1px solid #334155;
    border-radius: 8px;
    padding: 14px 16px;
}

.user-summary-grid span {
    display: block;
    color: #94a3b8;
    font-size: 0.76rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.user-summary-grid strong {
    display: block;
    margin-top: 6px;
    color: #f8fafc;
    font-size: 1.55rem;
}

.user-filter-bar {
    display: grid;
    grid-template-columns: minmax(220px, 2fr) repeat(3, minmax(140px, 1fr));
    gap: 10px;
    margin-bottom: 14px;
}

.user-filter-bar input,
.user-filter-bar select,
.confirm-name-field input {
    width: 100%;
    background: #0f172a;
    border: 1px solid #334155;
    color: #f8fafc;
    border-radius: 8px;
    padding: 10px 12px;
    font: inherit;
}

.user-filter-bar input:focus,
.user-filter-bar select:focus,
.confirm-name-field input:focus {
    outline: none;
    border-color: #3b82f6;
    box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.account-status-badge {
    display: inline-flex;
    align-items: center;
    border-radius: 8px;
    padding: 6px 12px;
    font-size: 0.8rem;
    font-weight: 800;
    border: 1px solid transparent;
}

.account-status-badge.active {
    color: #34d399;
    background: rgba(16, 185, 129, 0.1);
    border-color: rgba(16, 185, 129, 0.25);
}

.account-status-badge.suspended {
    color: #fb7185;
    background: rgba(244, 63, 94, 0.1);
    border-color: rgba(244, 63, 94, 0.25);
}

.delete-warning-copy {
    background: rgba(244, 63, 94, 0.08);
    border: 1px solid rgba(244, 63, 94, 0.18);
    border-radius: 8px;
    padding: 12px;
    font-size: 0.88rem;
}

.confirm-name-field {
    display: block;
    color: #cbd5e1;
    font-size: 0.86rem;
    font-weight: 700;
    text-align: left;
    margin: 12px 0;
}

.confirm-name-field input {
    margin-top: 8px;
}

.modal-error {
    background: rgba(244, 63, 94, 0.12);
    border: 1px solid rgba(244, 63, 94, 0.28);
    color: #fecdd3;
    border-radius: 8px;
    padding: 10px 12px;
    margin-bottom: 14px;
    font-weight: 700;
}

.confirm-btn:disabled {
    opacity: 0.45;
    cursor: not-allowed;
    transform: none !important;
}
/* --- Desktop Layout (Full-Width / Stretched) --- */
.users-container {
    width: 100%;
    margin: 0;
    padding: 0; 
}

/* Tighten the gap between the Title and the Table */
.dashboard-header {
    margin-bottom: 1rem !important; 
    width: 100%;
}

.self-enroll-btn {
    background: linear-gradient(135deg, #2563eb, #0891b2);
    color: white;
    border: 1px solid rgba(147, 197, 253, 0.35);
    padding: 12px 18px;
    border-radius: 8px;
    font-weight: 800;
    cursor: pointer;
    box-shadow: 0 10px 24px rgba(37, 99, 235, 0.25);
    white-space: nowrap;
}

.self-enroll-btn:hover {
    transform: translateY(-1px);
    box-shadow: 0 14px 30px rgba(37, 99, 235, 0.35);
}

.add-user-btn {
    background-color: #3b82f6;
    color: white;
    border: none;
    padding: 10px 20px;
    border-radius: 8px;
    font-weight: 600;
    cursor: pointer;
    transition: background-color 0.2s;
}

.add-user-btn:hover {
    background-color: #2563eb;
}

/* --- Table Wrapper (The Main Card) --- */
.table-wrapper {
    background-color: #1e293b;
    border: 1px solid #334155;
    border-radius: 12px;
    /* auto (not hidden): action buttons must never be clipped at 1366-1920px */
    overflow-x: auto;
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
    width: 100%;
}

/* --- Dark Mode Table Styling --- */
.users-table {
    width: 100%;
    min-width: 1280px;
    border-collapse: collapse;
    table-layout: fixed;
    text-align: left;
    color: #f8fafc;
}

.users-table th:nth-child(1),
.users-table td:nth-child(1) {
    width: 20%;
}

.users-table th:nth-child(2),
.users-table td:nth-child(2) {
    width: 13%;
}

.users-table th:nth-child(3),
.users-table td:nth-child(3) {
    width: 22%;
}

.users-table th:nth-child(4),
.users-table td:nth-child(4) {
    width: 10%;
}

.users-table th:nth-child(5),
.users-table td:nth-child(5) {
    width: 12%;
}

.users-table th:nth-child(6),
.users-table td:nth-child(6) {
    width: 9%;
}

.users-table th:nth-child(7),
.users-table td:nth-child(7) {
    width: 14%;
}

.users-table th {
    background-color: rgba(15, 23, 42, 0.4);
    padding: 18px 24px;
    font-size: 0.75rem;
    text-transform: uppercase;
    color: #94a3b8;
    font-weight: 700;
    letter-spacing: 0.1em;
    border-bottom: 1px solid #334155;
}

/* --- UPDATED: Aligns "ACTIONS" header to the center --- */
.users-table th:last-child {
    text-align: center;
}

.users-table td {
    padding: 18px 24px;
    border-bottom: 1px solid #334155;
    font-size: 0.95rem;
    vertical-align: middle; 
}

.users-table tbody tr:hover {
    background-color: rgba(51, 65, 85, 0.3); 
}

/* --- User Info Section --- */
.user-name-cell {
    font-weight: 700;
    min-width: 0;
    overflow-wrap: anywhere;
}

.user-identity {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
}

.user-avatar-small {
    width: 30px;
    height: 30px;
    background: linear-gradient(135deg, #6366f1, #3b82f6);
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
    font-weight: bold;
    font-size: 0.8rem;
    color: white;
    flex-shrink: 0;
}

.user-name-text {
    display: inline-flex;
    align-items: baseline;
    min-width: 0;
    white-space: normal;
    overflow-wrap: anywhere;
}

.email-cell { min-width: 0; white-space: normal; overflow-wrap: anywhere; }

/* --- Presence Status Tags --- */
.presence-tag {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 10px;
    white-space: nowrap;
    border-radius: 8px;
    font-size: 0.85rem;
    font-weight: 600;
}

.presence-tag.on-site {
    background: rgba(16, 185, 129, 0.1);
    color: #10b981;
    border: 1px solid rgba(16, 185, 129, 0.2);
}

.presence-tag.off-site {
    background: rgba(148, 163, 184, 0.1);
    color: #94a3b8;
    border: 1px solid rgba(148, 163, 184, 0.2);
}

/* --- Role Badges --- */
.role-cell {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 4px;
    min-width: 0;
}

.role-badge {
    padding: 4px 10px;
    border-radius: 6px;
    font-size: 0.7rem;
    font-weight: 800;
    text-transform: uppercase;
    white-space: nowrap;
}

.role-description {
    color: #b6c2d6;
    font-size: 0.76rem;
    font-weight: 500;
}

.role-fm { background: rgba(59, 130, 246, 0.15); color: #60a5fa; border: 1px solid rgba(59, 130, 246, 0.3); }
.role-tenant { background: rgba(245, 158, 11, 0.15); color: #fbbf24; border: 1px solid rgba(245, 158, 11, 0.3); }
.role-staff { background: rgba(139, 92, 246, 0.15); color: #a78bfa; border: 1px solid rgba(139, 92, 246, 0.3); }

/* --- ACTIONS COLUMN ALIGNMENT --- */
.actions-cell {
    text-align: center;
}

.action-btn {
    border: 1px solid transparent;
    font-weight: 600;
    font-size: 0.76rem;
    cursor: pointer;
    white-space: nowrap;
    border-radius: 8px;
    padding: 8px 10px;
    width: 118px;
    min-height: 36px;
    justify-content: center;
    background: rgba(15, 23, 42, 0.45);
    line-height: 1.1;
    transition: all 0.18s ease;
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

.action-btn svg {
    font-size: 0.95rem;
    flex-shrink: 0;
}

/* Compact horizontal group; wraps instead of clipping on narrow layouts */
.action-button-group {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 8px;
}

.action-neutral { 
    color: #60a5fa; 
    border-color: rgba(96, 165, 250, 0.18);
}

.action-neutral:hover,
.action-bio:hover {
    background: rgba(37, 99, 235, 0.22);
    border-color: rgba(96, 165, 250, 0.45);
}

.action-warning {
    color: #fda4af;
    border-color: rgba(244, 63, 94, 0.28);
    background: rgba(244, 63, 94, 0.08);
}

.action-warning:hover {
    background: rgba(244, 63, 94, 0.18);
    border-color: rgba(244, 63, 94, 0.5);
}

.action-restore {
    color: #34d399;
    border-color: rgba(16, 185, 129, 0.3);
    background: rgba(16, 185, 129, 0.08);
}

.action-restore:hover {
    background: rgba(16, 185, 129, 0.18);
    border-color: rgba(16, 185, 129, 0.5);
}

.action-bio {
    color: #38bdf8;
