2	   DESKTOP LAYOUT (Full-Width / Stretched)
3	   ========================================= */
4	
5	/* TIGHTENED: Reduced bottom margin to pull content up */
6	.dashboard-header {
7	    display: flex;
8	    justify-content: space-between;
9	    align-items: flex-start;
10	    margin-bottom: 1rem !important; 
11	}
12	
13	.management-container {
14	    width: 100%;
15	    max-width: none; 
16	    margin: 0;
17	    /* TIGHTENED: Reduced top padding from 1.5rem to 0.2rem */
18	    padding: 0.2rem 0 1.5rem 0; 
19	    color: #f8fafc;
20	    /* animation: slideUpFade 0.5s ease-out; */
21	}
22	
23	/* Header Tweaks */
24	.management-header h1 {
25	    font-size: 2rem;
26	    font-weight: 800;
27	    letter-spacing: -0.025em;
28	    margin-bottom: 0.25rem;
29	}
30	
31	/* --- Code Generator Card --- */
32	.code-generator-card {
33	    position: relative;
34	    width: 100%;
35	    box-sizing: border-box; 
36	    overflow: hidden;
37	    transition: all 0.3s ease;
38	    background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%);
39	    padding: 30px; 
40	    border-radius: 12px; 
41	    margin-top: 0; /* Ensures no extra gap above the card */
42	    margin-bottom: 30px;
43	    border: 1px solid #334155;
44	    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
45	}
46	
47	.code-generator-card::before {
48	    content: "";
49	    position: absolute;
50	    top: 0;
51	    left: 0;
52	    width: 4px;
53	    height: 100%;
54	    background: #3b82f6; 
55	}
56	
57	.code-flex-row {
58	    display: flex;
59	    align-items: center;
60	    gap: 20px;
61	}
62	
63	.code-display-box {
64	    background: #020617; 
65	    padding: 14px 28px; 
66	    border-radius: 8px; 
67	    border: 1px dashed #3b82f6; 
68	    color: #60a5fa; 
69	    font-family: 'JetBrains Mono', 'Courier New', monospace; 
70	    font-weight: 700; 
71	    font-size: 1.6rem;
72	    letter-spacing: 4px;
73	    box-shadow: inset 0 2px 10px rgba(0,0,0,0.5);
74	    display: inline-block;
75	    min-width: 250px;
76	}
77	
78	/* --- Table Styles --- */
79	.table-container {
80	    width: 100%;
81	    box-sizing: border-box;
82	    background: #0f172a;
83	    border-radius: 16px;
84	    border: 1px solid #1e293b;
85	    box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.2);
86	    margin-top: 1rem;
87	    overflow: hidden;
88	}
89	
90	.management-table {
91	    width: 100%;
92	    border-collapse: collapse;
93	}
94	
95	.management-table th {
96	    background: rgba(30, 41, 59, 0.5);
97	    padding: 1.25rem 1.5rem;
98	    color: #64748b;
99	    font-size: 0.75rem;
100	    font-weight: 700;
101	    text-transform: uppercase;
102	    letter-spacing: 0.1em;
103	    text-align: left;
104	}
105	
106	.management-table td {
107	    padding: 1.25rem 1.5rem;
108	    border-bottom: 1px solid #1e293b;
109	    color: #e2e8f0;
110	    vertical-align: middle;
111	}
112	
113	.management-table tr:hover {
114	    background: rgba(59, 130, 246, 0.03); 
115	}
116	
117	/* Personnel Info Styling */
118	.user-info {
119	    display: flex;
120	    align-items: center;
121	    gap: 12px;
122	}
123	
124	.user-initial {
125	    width: 32px;
126	    height: 32px;
127	    background: #3b82f6;
128	    color: white;
129	    border-radius: 50%;
130	    display: flex;
131	    justify-content: center;
132	    align-items: center;
133	    font-weight: 700;
134	    font-size: 0.85rem;
135	}
136	
137	/* --- Status & Action Buttons --- */
138	.status-badge {
139	    padding: 6px 12px;
140	    border-radius: 6px;
141	    font-size: 0.75rem;
142	    font-weight: 700;
143	    text-transform: uppercase;
144	    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
145	    letter-spacing: 0.5px;
146	}
147	
148	.status-badge.active {
149	    background: rgba(16, 185, 129, 0.1);
150	    color: #10b981;
151	    border: 1px solid rgba(16, 185, 129, 0.2);
152	}
153	
154	
155	.status-badge.pending {
156	    background: rgba(59, 130, 246, 0.12);
157	    color: #60a5fa;
158	    border: 1px solid rgba(59, 130, 246, 0.25);
159	}
160	
161	.status-badge.used {
162	    background: rgba(148, 163, 184, 0.12);
163	    color: #cbd5e1;
164	    border: 1px solid rgba(148, 163, 184, 0.25);
165	}
166	
167	/* --- Pending-invite expiry countdown block --- */
168	.invite-expiry-block {
169	    display: flex;
170	    flex-direction: column;
171	    gap: 4px;
172	}
173	
174	.invite-expiry-remaining {
175	    display: inline-flex;
176	    align-items: center;
177	    gap: 6px;
178	    color: #e2e8f0;
179	    font-size: 0.85rem;
180	    font-weight: 700;
181	}
182	
183	.invite-expiry-remaining svg {
184	    color: #60a5fa;
185	    font-size: 1rem;
186	}
187	
188	.invite-expiry-absolute {
189	    color: #b6c2d6;
190	    font-size: 0.78rem;
191	    font-weight: 500;
192	}
193	
194	.code-header-row {
195	    display: flex;
196	    justify-content: space-between;
197	    align-items: center;
198	    gap: 16px;
199	    margin-bottom: 10px;
200	}
201	
202	.code-header-row h3 {
203	    margin: 0;
204	}
205	
206	.code-header-hint {
207	    margin: 0;
208	    color: #94a3b8;
209	    font-size: 0.8rem;
210	    font-weight: 500;
211	}
212	
213	.code-subtext {
214	    color: #b6c2d6;
215	    font-size: 0.85rem;
216	    margin-bottom: 25px;
217	}
218	
219	.generate-invite-btn {
220	    background: #3b82f6;
221	    color: white;
222	    padding: 14px 24px;
223	}
224	
225	.code-copy-note {
226	    margin-top: 15px;
227	    color: #10b981;
228	    font-size: 0.85rem;
229	    font-weight: 600;
230	}
231	
232	.invite-code-cell {
233	    font-family: monospace;
234	    font-weight: bold;
235	    letter-spacing: 1px;
236	}
237	
238	.table-empty-cell {
239	    text-align: center;
240	    padding: 40px;
241	    color: #94a3b8;
242	}
243	/* Badge specific for "USED" or expired statuses */
244	.status-badge.expired {
245	    background: rgba(244, 63, 94, 0.1);
246	    color: #f43f5e;
247	    border: 1px solid rgba(244, 63, 94, 0.2);
248	}
249	
250	.edit-btn {
251	    color: #94a3b8;
252	    background: #1e293b;
253	    padding: 8px 16px;
254	    border-radius: 6px;
255	    font-size: 0.8rem;
256	    font-weight: 600;
257	    transition: all 0.2s;
258	    margin-right: 8px;
259	    border: none;
260	    cursor: pointer;
261	}
262	
263	.edit-btn:hover {
264	    color: #fff;
265	    background: #334155;
266	}
267	
268	.revoke-btn {
269	    color: #f43f5e;
270	    font-size: 0.8rem;
271	    font-weight: 600;
272	    background: rgba(244, 63, 94, 0.1); 
273	    border: 1px solid rgba(244, 63, 94, 0.2);
274	    padding: 8px 16px;
275	    border-radius: 6px;
276	    cursor: pointer;
277	    transition: all 0.2s;
278	}
279	
280	.revoke-btn:hover {
281	    background: #f43f5e;
282	    color: white;
283	    box-shadow: 0 0 15px rgba(244, 63, 94, 0.4);
284	}
285	
286	/* =========================================
287	   CUSTOM MODAL DESIGN (Security Deletion)
288	   ========================================= */
289	
290	.modal-overlay {
291	    position: fixed;
292	    top: 0; left: 0; width: 100%; height: 100%;
293	    background: rgba(2, 6, 23, 0.85);
294	    backdrop-filter: blur(8px);
295	    display: flex; justify-content: center; align-items: center;
296	    z-index: 2000;
297	}
298	
299	.modal-content {
300	    background: #1e293b;
301	    padding: 30px;
302	    border-radius: 16px;
303	    max-width: 450px;
304	    width: 90%;
305	    text-align: center;
306	    border: 1px solid #334155;
307	    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
308	}
309	
310	.delete-variant {
311	    border: 1px solid rgba(244, 63, 94, 0.3) !important;
312	    box-shadow: 0 0 30px rgba(244, 63, 94, 0.1) !important;
313	}
314	
315	.red-glow {
316	    text-shadow: 0 0 15px rgba(244, 63, 94, 0.8);
317	    font-size: 2.5rem;
318	    display: block;
319	    margin-bottom: 10px;
320	}
321	
322	.warning-subtext {
323	    background: rgba(244, 63, 94, 0.05);
324	    padding: 15px;
325	    border-radius: 8px;
326	    border: 1px solid rgba(244, 63, 94, 0.1);
327	    color: #94a3b8;
328	    font-size: 0.85rem;
329	    line-height: 1.5;
330	    margin: 15px 0;
331	}
332	
333	.modal-actions {
334	    display: flex;
335	    justify-content: center;
336	    gap: 12px;
337	    margin-top: 20px;
338	}
339	
340	.cancel-btn {
341	    background: #334155;
342	    color: #cbd5e1;
343	    border: none;
344	    padding: 12px 24px;
345	    border-radius: 8px;
346	    font-weight: 600;
347	    cursor: pointer;
348	}
349	
350	.confirm-delete-btn {
351	    background: #ef4444;
352	    color: white;
353	    border: none;
354	    padding: 12px 24px;
355	    border-radius: 8px;
356	    font-weight: 700;
357	    cursor: pointer;
358	    transition: all 0.2s;
359	}
360	
361	.confirm-delete-btn:hover {
362	    background: #dc2626;
363	    box-shadow: 0 0 15px rgba(239, 68, 68, 0.4);
364	}
365	
366	/* --- Toast Notifications --- */
367	.toast-notification {
368	    position: fixed;
369	    top: 30px;
370	    right: 30px;
371	    min-width: 300px;
372	    padding: 16px 20px;
373	    border-radius: 12px;
374	    background: #1e293b;
375	    border: 1px solid #334155;
376	    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.4);
377	    display: flex;
378	    align-items: center;
379	    gap: 12px;
380	    z-index: 1000;
381	    animation: toastSlideIn 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55);
382	}
383	
384	.toast-notification.success { border-left: 4px solid #10b981; }
385	.toast-notification.error { border-left: 4px solid #f43f5e; }
386	
387	/* =========================================
388	   MOBILE RESPONSIVENESS (Under 768px)
389	   ========================================= */
390	
391	@media (max-width: 768px) {
392	    .management-container {
393	        padding: 1rem 0;
394	    }
395	
396	    .dashboard-header {
397	        flex-direction: column;
398	        align-items: flex-start;
399	        gap: 10px;
400	        margin-bottom: 20px;
401	    }
402	
403	    .code-generator-card > div:first-child {
404	        flex-direction: column !important;
405	        align-items: flex-start !important;
406	        gap: 12px;
407	    }
408	
409	    .code-generator-card div[style*="text-align: right"] {
410	        text-align: left !important;
411	        width: 100%;
412	    }
413	
414	    .code-generator-card h3 {
415	        font-size: 1.1rem;
416	        margin-bottom: 5px;
417	    }
418	
419	    .code-flex-row {
420	        flex-direction: column;
421	        align-items: stretch;
422	        gap: 15px;
423	    }
424	
425	    .code-display-box {
426	        font-size: 1.2rem;
427	        letter-spacing: 3px;
428	        text-align: center;
429	        width: 100%;
430	        padding: 12px;
431	    }
432	
433	    .code-generator-card .edit-btn {
434	        width: 100%;
435	        margin: 0;
436	        padding: 15px !important;
437	    }
438	
439	    .management-table thead {
440	        display: none; 
441	    }
442	
443	    .management-table, 
444	    .management-table tbody, 
445	    .management-table tr, 
446	    .management-table td {
447	        display: block;
448	        width: 100%;
449	    }
450	
451	    .management-table tr {
452	        margin-bottom: 15px;
453	        background: #1e293b; 
454	        border: 1px solid #334155;
455	        border-radius: 12px;
456	        padding: 8px;
457	        box-shadow: 0 4px 6px rgba(0,0,0,0.1);
458	    }
459	
460	    .management-table td {
461	        display: flex;
462	        justify-content: space-between;
463	        align-items: center;
464	        padding: 12px 10px;
465	        border-bottom: 1px solid rgba(255, 255, 255, 0.05);
466	    }
467	
468	    .management-table td:last-child {
469	        border-bottom: none;
470	        justify-content: center;
471	        gap: 10px;
472	        padding: 20px 10px 10px 10px;
473	    }
474	
475	    .management-table td::before {
476	        content: attr(data-label);
477	        font-weight: 700;
478	        text-transform: uppercase;
479	        font-size: 0.65rem;
480	        color: #94a3b8;
481	        letter-spacing: 0.05em;
482	    }
483	
484	    .user-info {
485	        justify-content: flex-end;
486	        gap: 8px;
487	    }
488	
489	    .user-initial {
490	        width: 28px;
491	        height: 28px;
492	        font-size: 0.75rem;
493	    }
494	
495	    .management-table .edit-btn, 
496	    .management-table .revoke-btn {
497	        flex: 1;
498	        text-align: center;
499	        padding: 10px;
500	        margin: 0;
501	    }
502	
503	    .modal-content {
504	        width: 95%;
505	        padding: 20px;
506	    }
507	
508	    .toast-notification {
509	        top: 15px;
510	        right: 15px;
511	        left: 15px;
512	        min-width: auto;
513	    }
514	}
515	
516	/* --- Animations --- */
517	@keyframes slideUpFade {
518	    from { opacity: 0; transform: translateY(20px); }
519	    to { opacity: 1; transform: translateY(0); }
520	}
521	
522	@keyframes toastSlideIn {
523	    from { transform: translateX(120%); opacity: 0; }
524	    to { transform: translateX(0); opacity: 1; }
525	}
526	
527	.expired-box {
528	    border: 1px solid #f43f5e !important;
529	    color: #f43f5e !important;
530	    opacity: 0.6;
531	    text-decoration: line-through;
532	}
533	
534	/* =========================================
535	   SECURITY REVIEW TABLE POLISH (scoped — does not affect other management tables)
536	   ========================================= */
537	.review-table-container { overflow-x: auto; } /* scroll only if the laptop window is very narrow */
538	
539	.security-review-table { min-width: 900px; }   /* gives the 6 columns room; fits a 1366px laptop without scroll */
540	.security-review-table td { vertical-align: top; }
541	.security-review-table .status-badge { white-space: nowrap; } /* "Pending Review" stays on one line */
542	
543	.review-status-cell { min-width: 150px; }
544	.review-status-cell .review-current-status { display: inline-block; margin-top: 8px; }
545	
546	.review-resolution-cell { min-width: 240px; }
547	.review-resolution { display: flex; flex-direction: column; gap: 8px; align-items: flex-start; }
548	.review-save-btn { margin: 0; align-self: flex-start; }
549	.review-reviewer { color: #64748b; font-size: 0.75rem; }
550	
551	.review-select,
552	.review-textarea {
553	    width: 100%;
554	    background: #0b0f1a;
555	    border: 1px solid #334155;
556	    color: #f8fafc;
557	    border-radius: 8px;
558	    padding: 8px 10px;
559	    font-size: 0.85rem;
560	    outline: none;
561	    transition: border-color 0.2s, box-shadow 0.2s;
562	}
563	.review-select:focus,
564	.review-textarea:focus { border-color: #3b82f6; box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15); }
565	.review-select option { background: #0b0f1a; color: #f8fafc; }
566	.review-textarea { resize: vertical; min-height: 52px; font-family: inherit; }
567	
568	/* Phones: keep the existing card behavior; drop min-widths so nothing overflows. */
569	@media (max-width: 768px) {
570	    .security-review-table { min-width: 0; }
571	    .review-status-cell,
572	    .review-resolution-cell { min-width: 0; }
573	    .security-review-table td.review-status-cell,
574	    .security-review-table td.review-resolution-cell {
575	        flex-direction: column;
576	        align-items: stretch;
577	        gap: 8px;
578	    }
579	}

