.edit-btn {
    color: #94a3b8;
    background: #1e293b;
    padding: 8px 16px;
    border-radius: 6px;
    font-size: 0.8rem;
    font-weight: 600;
    transition: all 0.2s;
    margin-right: 8px;
    border: none;
    cursor: pointer;
}

.edit-btn:hover {
    color: #fff;
    background: #334155;
}

.revoke-btn {
    color: #f43f5e;
    font-size: 0.8rem;
    font-weight: 600;
    background: rgba(244, 63, 94, 0.1); 
    border: 1px solid rgba(244, 63, 94, 0.2);
    padding: 8px 16px;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.2s;
}

.revoke-btn:hover {
    background: #f43f5e;
    color: white;
    box-shadow: 0 0 15px rgba(244, 63, 94, 0.4);
}

