   CUSTOM MODAL DESIGN (Security Deletion)
   ========================================= */

.modal-overlay {
    position: fixed;
    top: 0; left: 0; width: 100%; height: 100%;
    background: rgba(2, 6, 23, 0.85);
    backdrop-filter: blur(8px);
    display: flex; justify-content: center; align-items: center;
    z-index: 2000;
}

.modal-content {
    background: #1e293b;
    padding: 30px;
    border-radius: 16px;
    max-width: 450px;
    width: 90%;
    text-align: center;
    border: 1px solid #334155;
    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
}

.delete-variant {
    border: 1px solid rgba(244, 63, 94, 0.3) !important;
    box-shadow: 0 0 30px rgba(244, 63, 94, 0.1) !important;
}

.red-glow {
    text-shadow: 0 0 15px rgba(244, 63, 94, 0.8);
    font-size: 2.5rem;
    display: block;
    margin-bottom: 10px;
}

.warning-subtext {
    background: rgba(244, 63, 94, 0.05);
    padding: 15px;
    border-radius: 8px;
    border: 1px solid rgba(244, 63, 94, 0.1);
    color: #94a3b8;
    font-size: 0.85rem;
    line-height: 1.5;
    margin: 15px 0;
}

.modal-actions {
    display: flex;
    justify-content: center;
    gap: 12px;
    margin-top: 20px;
}

.cancel-btn {
    background: #334155;
    color: #cbd5e1;
    border: none;
    padding: 12px 24px;
    border-radius: 8px;
    font-weight: 600;
    cursor: pointer;
}

.confirm-delete-btn {
    background: #ef4444;
    color: white;
    border: none;
    padding: 12px 24px;
    border-radius: 8px;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.2s;
}

.confirm-delete-btn:hover {
    background: #dc2626;
    box-shadow: 0 0 15px rgba(239, 68, 68, 0.4);
}

