   MOBILE RESPONSIVENESS (Under 768px)
   ========================================= */

@media (max-width: 768px) {
    .management-container {
        padding: 1rem 0;
    }

    .dashboard-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 10px;
        margin-bottom: 20px;
    }

    .code-generator-card > div:first-child {
        flex-direction: column !important;
        align-items: flex-start !important;
        gap: 12px;
    }

    .code-generator-card div[style*="text-align: right"] {
        text-align: left !important;
        width: 100%;
    }

    .code-generator-card h3 {
        font-size: 1.1rem;
        margin-bottom: 5px;
    }

    .code-flex-row {
        flex-direction: column;
        align-items: stretch;
        gap: 15px;
    }

    .code-display-box {
        font-size: 1.2rem;
        letter-spacing: 3px;
        text-align: center;
        width: 100%;
        padding: 12px;
    }

    .code-generator-card .edit-btn {
        width: 100%;
        margin: 0;
        padding: 15px !important;
    }

    .management-table thead {
        display: none; 
    }

    .management-table, 
    .management-table tbody, 
    .management-table tr, 
    .management-table td {
        display: block;
        width: 100%;
    }

    .management-table tr {
        margin-bottom: 15px;
        background: #1e293b; 
        border: 1px solid #334155;
        border-radius: 12px;
        padding: 8px;
        box-shadow: 0 4px 6px rgba(0,0,0,0.1);
    }

    .management-table td {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 12px 10px;
        border-bottom: 1px solid rgba(255, 255, 255, 0.05);
    }

    .management-table td:last-child {
        border-bottom: none;
        justify-content: center;
        gap: 10px;
        padding: 20px 10px 10px 10px;
    }

    .management-table td::before {
        content: attr(data-label);
        font-weight: 700;
        text-transform: uppercase;
        font-size: 0.65rem;
        color: #94a3b8;
        letter-spacing: 0.05em;
    }

    .user-info {
        justify-content: flex-end;
        gap: 8px;
    }

    .user-initial {
        width: 28px;
        height: 28px;
        font-size: 0.75rem;
    }

    .management-table .edit-btn, 
    .management-table .revoke-btn {
        flex: 1;
        text-align: center;
        padding: 10px;
        margin: 0;
    }

    .modal-content {
        width: 95%;
        padding: 20px;
    }

    .toast-notification {
        top: 15px;
        right: 15px;
        left: 15px;
        min-width: auto;
    }
}

/* --- Animations --- */
@keyframes slideUpFade {
    from { opacity: 0; transform: translateY(20px); }
    to { opacity: 1; transform: translateY(0); }
}

@keyframes toastSlideIn {
    from { transform: translateX(120%); opacity: 0; }
    to { transform: translateX(0); opacity: 1; }
}

.expired-box {
    border: 1px solid #f43f5e !important;
    color: #f43f5e !important;
    opacity: 0.6;
    text-decoration: line-through;
}

/* =========================================
   SECURITY REVIEW TABLE POLISH (scoped — does not affect other management tables)
   ========================================= */
.review-table-container { overflow-x: auto; } /* scroll only if the laptop window is very narrow */

.security-review-table { min-width: 900px; }   /* gives the 6 columns room; fits a 1366px laptop without scroll */
.security-review-table td { vertical-align: top; }
.security-review-table .status-badge { white-space: nowrap; } /* "Pending Review" stays on one line */

.review-status-cell { min-width: 150px; }
.review-status-cell .review-current-status { display: inline-block; margin-top: 8px; }

.review-resolution-cell { min-width: 240px; }
.review-resolution { display: flex; flex-direction: column; gap: 8px; align-items: flex-start; }
.review-save-btn { margin: 0; align-self: flex-start; }
.review-reviewer { color: #64748b; font-size: 0.75rem; }

.review-select,
.review-textarea {
    width: 100%;
    background: #0b0f1a;
    border: 1px solid #334155;
    color: #f8fafc;
    border-radius: 8px;
    padding: 8px 10px;
    font-size: 0.85rem;
    outline: none;
    transition: border-color 0.2s, box-shadow 0.2s;
}
.review-select:focus,
.review-textarea:focus { border-color: #3b82f6; box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15); }
.review-select option { background: #0b0f1a; color: #f8fafc; }
.review-textarea { resize: vertical; min-height: 52px; font-family: inherit; }

/* Phones: keep the existing card behavior; drop min-widths so nothing overflows. */
@media (max-width: 768px) {
    .security-review-table { min-width: 0; }
    .review-status-cell,
    .review-resolution-cell { min-width: 0; }
    .security-review-table td.review-status-cell,
    .security-review-table td.review-resolution-cell {
        flex-direction: column;
        align-items: stretch;
        gap: 8px;
    }
}

